python3 << 'PY'
#!/usr/bin/env python3
import json, subprocess

NOTE_MAP = {"C":0,"C#":1,"D":2,"D#":3,"E":4,"F":5,"F#":6,"G":7,"G#":8,"A":9,"A#":10,"B":11}

def note_num(s):
    if s is None or s in ("","---"): return None
    if s in ("OFF","==","off"): return 97
    s=s.strip().upper().replace(" ","")
    if len(s)==3 and s[1]=="-":
        n=NOTE_MAP[s[0]]; oct=int(s[2])
    elif len(s)==3 and s[1]=="#":
        n=NOTE_MAP[s[0:2]]; oct=int(s[2])
    else:
        raise ValueError(s)
    return 1+n+oct*12

batch=[]
def cell(p,r,ch,note=None,ins=None,vol=None,fx=None,param=None):
    d={"name":"pattern_set_cell","arguments":{"pattern":p,"row":r,"channel":ch}}
    a=d["arguments"]
    if note is not None: a["note"]=note_num(note) if isinstance(note,str) else note
    if ins is not None: a["instrument"]=ins
    if vol is not None: a["volume"]=vol
    if fx is not None: a["effect"]=fx
    if param is not None: a["effect_param"]=param
    batch.append(d)

# order + lengths
for pos,pat in enumerate([0,1,2,3,4,5,2,3,6,7,4,5]):
    batch.append({"name":"order_set","arguments":{"position":pos,"pattern":pat}})
for p in range(8):
    batch.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":64}})
    batch.append({"name":"pattern_clear","arguments":{"pattern":p}})

# Arpeggios
arp_am=["A-4","C-5","E-5","A-5","E-5","C-5","A-4","E-4"]
arp_f =["F-4","A-4","C-5","F-5","C-5","A-4","F-4","C-4"]
