#!/usr/bin/env python3
"""Restore patterns after sample testing cleared pattern 0; ensure song intact."""
import json, subprocess

def ft2_batch(batch, path="/workspace/scripts/final_batch.json"):
    with open(path,"w") as f: json.dump(batch,f)
    r=subprocess.run(["ft2","batch",path],capture_output=True,text=True)
    # count errors
    err=r.stdout.count('"isError": true') + r.stdout.count('"isError":true')
    print(f"batch {len(batch)} cmds, errors={err}, rc={r.returncode}")
    return r

NOTE_MAP={"C":0,"C#":1,"D":2,"D#":3,"E":4,"F":5,"F#":6,"G":7,"G#":8,"A":9,"A#":10,"B":11}
def nn(s):
    if s in ("OFF","=="): return 97
    s=s.strip().upper()
    if len(s)==3 and s[1]=="-":
        return 1+NOTE_MAP[s[0]]+int(s[2])*12
    if len(s)==3 and s[1]=="#":
        return 1+NOTE_MAP[s[:2]]+int(s[2])*12
    raise ValueError(s)

batch=[]
def cell(p,r,ch,note=None,ins=None,vol=None,fx=None,param=None):
    d={"name":"pattern_set_cell","arguments":{"pattern":p,"row":r,"channel":ch}}
    a=d["arguments"]
    if note is not None: a["note"]=nn(note) if isinstance(note,str) else note
    if ins is not None: a["instrument"]=ins
    if vol is not None: a["volume"]=vol
    if fx is not None: a["effect"]=fx
    if param is not None: a["effect_param"]=param
    batch.append(d)

